    def setUp(self):
        self.entries = pennywise.parse(
            "2024-03-01 salary 2500.00\n"
            "2024-03-02 groceries -42.50\n"
            "2024-04-02 Groceries -10\n"
            "2024-03-05 rent -900\n"
        )

